<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { api } from './api'
const props=defineProps({currentUser:{type:Object,required:true}})
const flows=ref([]),selected=ref(null),graph=ref({nodes:[],edges:[]}),selectedNodeId=ref(null),error=ref(''),success=ref(''),connectFrom=ref(null),canvas=ref(null),search=ref(''),tags=ref([]),fields=ref([]),agents=ref([])
const createForm=reactive({name:'',trigger_type:'manual',trigger_value:''})
const draft=reactive({title:'',trigger_type:'manual',keywords:'',match_type:'exact',stop_on_reply:false,text:'',seconds:60,condition_field:'service_window',operator:'open',value:'',url:'',method:'POST',body:'',add_tag:'',remove_tag:'',assign_user:'',set_field:'',set_field_value:''})
const groups=[{label:'Messages',items:[['send_message','Text','💬'],['image','Image','🖼'],['video','Video','🎥'],['audio','Audio','🎵'],['file','File','📎']]},{label:'Interactive',items:[['question','Question','❓'],['interactive','Interactive message','🔘'],['template','Template message','🧩']]},{label:'Contact',items:[['add_tag','Add tag','🏷'],['remove_tag','Remove tag','✂'],['set_field','Set custom field','📝'],['assign_user','Assign agent','👤']]},{label:'Flow control',items:[['condition','Condition','⑂'],['delay','Delay','⏱'],['set_status','Conversation status','✓']]},{label:'Integrations',items:[['http_request','HTTP request','🌐']]}]
const filteredGroups=computed(()=>groups.map(g=>({...g,items:g.items.filter(i=>i[1].toLowerCase().includes(search.value.toLowerCase()))})).filter(g=>g.items.length)),selectedNode=computed(()=>graph.value.nodes.find(n=>n.id===selectedNodeId.value)||null),nodeWidth=240
function labelFor(t){return groups.flatMap(g=>g.items).find(i=>i[0]===t)?.[1]||(t==='trigger'?'Start Bot Flow':'Block')} function iconFor(t){return groups.flatMap(g=>g.items).find(i=>i[0]===t)?.[2]||(t==='trigger'?'🤖':'⚡')}
function summary(n){const c=n.config||{};if(n.node_type==='trigger')return c.trigger_value||c.trigger_type||'Manual';if(n.node_type==='send_message')return c.text||'Configure message';if(n.node_type==='condition')return `${c.field||'service_window'} ${c.operator||'open'} ${c.value||''}`.trim();if(n.node_type==='delay')return `${c.seconds||60}s`;if(n.node_type==='http_request')return `${c.method||'POST'} ${c.url||'Configure URL'}`;return n.title||'Configure block'}
function nodeById(id){return graph.value.nodes.find(n=>n.id===id)} function edgePath(e){const s=nodeById(e.source_node_id),t=nodeById(e.target_node_id);if(!s||!t)return'';const sx=s.position_x+nodeWidth,sy=s.position_y+(e.source_handle==='yes'?70:e.source_handle==='no'?88:52),tx=t.position_x,ty=t.position_y+52,dx=Math.max(70,(tx-sx)/2);return `M ${sx} ${sy} C ${sx+dx} ${sy}, ${tx-dx} ${ty}, ${tx} ${ty}`}
async function refs(){for(const [r,set] of [[api.contactTags(),tags],[api.contactFields(),fields],[api.agents(),agents]]){try{set.value=await r}catch{}}} async function loadFlows(auto=true){try{flows.value=await api.flows();if(auto&&!selected.value&&flows.value.length)await selectFlow(flows.value[0])}catch(e){error.value=e.message}}
async function createFlow(){try{const f=await api.createFlow({name:createForm.name,trigger_type:createForm.trigger_type,trigger_value:createForm.trigger_type==='keyword'?createForm.trigger_value:null,stop_on_reply:false});createForm.name='';createForm.trigger_value='';await loadFlows(false);await selectFlow(f)}catch(e){error.value=e.message}}
async function selectFlow(flow){selected.value=await api.flow(flow.id||flow);graph.value=await api.flowGraph(selected.value.id);selectedNodeId.value=null;connectFrom.value=null;if(!graph.value.nodes.length)await seedGraph()}
async function seedGraph(){let trigger=await api.addFlowNode(selected.value.id,{node_type:'trigger',title:'Start Bot Flow',config:{trigger_type:selected.value.trigger_type,trigger_value:selected.value.trigger_value,match_type:'exact',stop_on_reply:selected.value.stop_on_reply},position_x:80,position_y:80});graph.value.nodes.push(trigger);let prev=trigger,y=230;for(const step of selected.value.steps||[]){const node=await api.addFlowNode(selected.value.id,{node_type:step.step_type,title:null,config:step.config||{},position_x:380,position_y:y});graph.value.nodes.push(node);graph.value.edges.push(await api.addFlowEdge(selected.value.id,{source_node_id:prev.id,source_handle:'next',target_node_id:node.id,target_handle:'input'}));prev=node;y+=150}}
async function addNode(type){const count=graph.value.nodes.length,node=await api.addFlowNode(selected.value.id,{node_type:type,title:labelFor(type),config:type==='delay'?{seconds:60}:type==='condition'?{field:'service_window',operator:'open',value:''}:type==='http_request'?{method:'POST',url:'',body:''}:{},position_x:360+(count%3)*280,position_y:90+Math.floor(count/3)*170});graph.value.nodes.push(node);selectNode(node)}
function hydrate(n){const c=n?.config||{};Object.assign(draft,{title:n?.title||'',trigger_type:c.trigger_type||selected.value?.trigger_type||'manual',keywords:c.trigger_value||selected.value?.trigger_value||'',match_type:c.match_type||'exact',stop_on_reply:c.stop_on_reply??selected.value?.stop_on_reply??false,text:c.text||'',seconds:c.seconds||60,condition_field:c.field||'service_window',operator:c.operator||'open',value:c.value||'',url:c.url||'',method:c.method||'POST',body:c.body||'',add_tag:c.add_tag||'',remove_tag:c.remove_tag||'',assign_user:c.assign_user||'',set_field:c.set_field||'',set_field_value:c.set_field_value||''})} function selectNode(n){selectedNodeId.value=n.id;hydrate(n)}
async function saveNode(){const n=selectedNode.value;if(!n)return;let config={...(n.config||{})};if(n.node_type==='trigger'){config={...config,trigger_type:draft.trigger_type,trigger_value:draft.trigger_type==='keyword'?draft.keywords:null,match_type:draft.match_type,stop_on_reply:draft.stop_on_reply,add_tag:draft.add_tag||null,remove_tag:draft.remove_tag||null,assign_user:draft.assign_user||null,set_field:draft.set_field||null,set_field_value:draft.set_field_value||null};selected.value=await api.updateFlow(selected.value.id,{name:draft.title||selected.value.name,trigger_type:config.trigger_type,trigger_value:config.trigger_value,stop_on_reply:config.stop_on_reply})}if(n.node_type==='send_message')config.text=draft.text;if(n.node_type==='delay')config.seconds=Number(draft.seconds);if(n.node_type==='condition')config={...config,field:draft.condition_field,operator:draft.operator,value:draft.value};if(n.node_type==='http_request')config={...config,method:draft.method,url:draft.url,body:draft.body};const updated=await api.updateFlowNode(selected.value.id,n.id,{title:draft.title||null,config});graph.value.nodes[graph.value.nodes.findIndex(x=>x.id===n.id)]=updated;success.value='Changes saved.';setTimeout(()=>success.value='',1800)}
async function deleteNode(n){if(n.node_type==='trigger'||!confirm('Delete this block and its connections?'))return;await api.deleteFlowNode(selected.value.id,n.id);graph.value.nodes=graph.value.nodes.filter(x=>x.id!==n.id);graph.value.edges=graph.value.edges.filter(e=>e.source_node_id!==n.id&&e.target_node_id!==n.id);selectedNodeId.value=null} async function dragEnd(ev,n){const r=canvas.value.getBoundingClientRect(),x=Math.max(20,Math.round(ev.clientX-r.left-30+canvas.value.scrollLeft)),y=Math.max(20,Math.round(ev.clientY-r.top-20+canvas.value.scrollTop));n.position_x=x;n.position_y=y;await api.updateFlowNode(selected.value.id,n.id,{position_x:x,position_y:y})}
function armConnection(n,handle='next'){connectFrom.value={node_id:n.id,handle}} async function connectTo(n){if(!connectFrom.value||connectFrom.value.node_id===n.id)return;try{graph.value.edges.push(await api.addFlowEdge(selected.value.id,{source_node_id:connectFrom.value.node_id,source_handle:connectFrom.value.handle,target_node_id:n.id,target_handle:'input'}));connectFrom.value=null}catch(e){error.value=e.message}} async function deleteEdge(e){await api.deleteFlowEdge(selected.value.id,e.id);graph.value.edges=graph.value.edges.filter(x=>x.id!==e.id)} async function updateStatus(status){selected.value=await api.updateFlow(selected.value.id,{status});await loadFlows(false)} onMounted(()=>{loadFlows();refs()})
</script>
<template><section class="visual-builder"><aside class="blocks-panel"><div class="blocks-head"><b>Flow blocks</b><small>Click a block to add it</small></div><input v-model="search" class="block-search" placeholder="Search blocks…"/><div class="block-groups"><section v-for="g in filteredGroups" :key="g.label"><h4>{{g.label}}</h4><button v-for="item in g.items" :key="item[0]" @click="addNode(item[0])"><span>{{item[2]}}</span>{{item[1]}}</button></section></div></aside><div class="builder-main"><header class="builder-toolbar"><div class="flow-picker"><select v-if="flows.length" :value="selected?.id||''" @change="selectFlow(Number($event.target.value))"><option v-for="f in flows" :key="f.id" :value="f.id">{{f.name}}</option></select><form @submit.prevent="createFlow"><input v-model="createForm.name" required placeholder="New flow…"/><select v-model="createForm.trigger_type"><option value="manual">Manual</option><option value="keyword">Keyword</option><option value="first_message">First message</option></select><input v-if="createForm.trigger_type==='keyword'" v-model="createForm.trigger_value" required placeholder="Keyword"/><button>Create</button></form></div><div v-if="selected" class="toolbar-actions"><span :class="['flow-state',selected.status]">{{selected.status}}</span><select :value="selected.status" @change="updateStatus($event.target.value)"><option value="draft">Draft</option><option value="active">Active</option><option value="paused">Paused</option></select></div></header><div v-if="selected" ref="canvas" class="flow-stage" @click.self="connectFrom=null"><svg class="edge-layer"><path v-for="e in graph.edges" :key="e.id" :d="edgePath(e)" @dblclick="deleteEdge(e)"/></svg><article v-for="n in graph.nodes" :key="n.id" class="graph-node" :class="[n.node_type,{selected:selectedNodeId===n.id}]" :style="{left:n.position_x+'px',top:n.position_y+'px'}" draggable="true" @dragend="dragEnd($event,n)" @click.stop="selectNode(n)"><header><span>{{iconFor(n.node_type)}}</span><strong>{{n.title||labelFor(n.node_type)}}</strong><button v-if="n.node_type!=='trigger'" @click.stop="deleteNode(n)">×</button></header><p>{{summary(n)}}</p><button class="input-port" @click.stop="connectTo(n)"></button><template v-if="n.node_type==='condition'"><button class="output-port yes" @click.stop="armConnection(n,'yes')"><i>TRUE</i></button><button class="output-port no" @click.stop="armConnection(n,'no')"><i>FALSE</i></button></template><button v-else class="output-port" @click.stop="armConnection(n,'next')"></button></article><div v-if="connectFrom" class="connect-hint">Select the input dot on the next block · click canvas to cancel</div></div></div><aside v-if="selectedNode" class="config-drawer"><div class="drawer-title"><div class="drawer-icon">{{iconFor(selectedNode.node_type)}}</div><div><h2>Configure {{labelFor(selectedNode.node_type)}}</h2><p>Define how this block should behave in the flow.</p></div></div><div class="drawer-scroll"><section class="config-section"><header><b>⚙ Basic Setup</b><small>Essential settings for this block.</small></header><label>Title<input v-model="draft.title"/></label><template v-if="selectedNode.node_type==='trigger'"><label>Trigger type<select v-model="draft.trigger_type"><option value="keyword">Keyword</option><option value="first_message">First message</option><option value="manual">Manual</option></select></label><label v-if="draft.trigger_type==='keyword'">Trigger Keywords<textarea v-model="draft.keywords" rows="4" placeholder="hello,hi,help"/></label><div v-if="draft.trigger_type==='keyword'" class="match-grid"><button :class="{active:draft.match_type==='exact'}" @click="draft.match_type='exact'"><b>Exact keyword match</b><small>Match exact keywords</small></button><button :class="{active:draft.match_type==='contains'}" @click="draft.match_type='contains'"><b>String match</b><small>Match when message contains text</small></button></div><label class="check"><input v-model="draft.stop_on_reply" type="checkbox"/> Stop flow when contact replies</label></template><label v-if="selectedNode.node_type==='send_message'">Message<textarea v-model="draft.text" rows="7"/></label><label v-if="selectedNode.node_type==='delay'">Delay in seconds<input v-model.number="draft.seconds" type="number" min="1"/></label><template v-if="selectedNode.node_type==='condition'"><label>Check<select v-model="draft.condition_field"><option value="service_window">24-hour service window</option><option value="tag">Contact tag</option><option value="custom_field">Custom field</option><option value="conversation_status">Conversation status</option><option value="assigned_user">Assigned agent</option></select></label><label>Operator<select v-model="draft.operator"><option value="open">Open / is</option><option value="closed">Closed / is not</option><option value="equals">Equals</option><option value="not_equals">Not equals</option><option value="contains">Contains</option><option value="empty">Empty</option><option value="not_empty">Not empty</option></select></label><label>Value<input v-model="draft.value"/></label></template><template v-if="selectedNode.node_type==='http_request'"><div class="http-grid"><label>Method<select v-model="draft.method"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select></label><label>URL<input v-model="draft.url" placeholder="https://…"/></label></div><label>Request body<textarea v-model="draft.body" rows="7" placeholder='{"contact_id":"{{contact.id}}"}'/></label></template></section><section v-if="selectedNode.node_type==='trigger'" class="config-section"><header><b>🏷 Automation Actions <em>Optional</em></b><small>Manage tags and team assignment.</small></header><div class="two-col"><label>Add tag<select v-model="draft.add_tag"><option value="">None</option><option v-for="t in tags" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Remove tag<select v-model="draft.remove_tag"><option value="">None</option><option v-for="t in tags" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Assign conversation to user<select v-model="draft.assign_user"><option value="">Unchanged</option><option v-for="a in agents" :key="a.id" :value="a.id">{{a.name}}</option></select></label></div></section><section v-if="selectedNode.node_type==='trigger'" class="config-section"><header><b>🗄 Data & Integrations <em>Optional</em></b><small>Store data in a contact custom field.</small></header><div class="two-col"><label>Save to custom field<select v-model="draft.set_field"><option value="">None</option><option v-for="f in fields" :key="f.id" :value="f.id">{{f.label}}</option></select></label><label v-if="draft.set_field">Value<input v-model="draft.set_field_value"/></label></div></section></div><footer class="drawer-footer"><button class="close" @click="selectedNodeId=null">× Close</button><button class="save" @click="saveNode">▣ Save Changes</button></footer></aside><p v-if="error" class="builder-toast error">{{error}}</p><p v-if="success" class="builder-toast">{{success}}</p></section></template>
<style scoped>
.visual-builder{height:100vh;display:grid;grid-template-columns:250px 1fr;position:relative;background:#eef4f7;color:#17352a}.blocks-panel{background:#fff;border-right:1px solid #dce5e8;overflow:auto;z-index:4}.blocks-head{padding:18px;border-bottom:1px solid #edf1f3}.blocks-head b,.blocks-head small{display:block}.blocks-head small{color:#7e9098;margin-top:3px}.block-search{margin:14px;width:calc(100% - 28px);padding:10px;border:1px solid #d9e2e5;border-radius:9px}.block-groups section{padding:0 12px 13px}.block-groups h4{font-size:10px;text-transform:uppercase;letter-spacing:.09em;color:#91a2aa}.block-groups button{width:100%;display:flex;gap:9px;padding:10px;border:0;border-bottom:1px solid #edf2f3;background:#fff;text-align:left;cursor:pointer}.builder-main{min-width:0;display:flex;flex-direction:column}.builder-toolbar{height:72px;background:#fff;border-bottom:1px solid #dce5e8;padding:12px 18px;display:flex;justify-content:space-between;align-items:center}.flow-picker,.flow-picker form,.toolbar-actions{display:flex;gap:8px;align-items:center}.builder-toolbar input,.builder-toolbar select{padding:9px;border:1px solid #d5dfe2;border-radius:8px}.builder-toolbar button{border:0;border-radius:8px;background:#16ad63;color:#fff;padding:10px 14px;font-weight:700}.flow-state{font-size:9px;padding:6px 9px;border-radius:999px;background:#edf1ef;text-transform:uppercase}.flow-state.active{background:#e5f8ec;color:#167648}.flow-stage{position:relative;flex:1;overflow:auto;min-height:700px;background-image:radial-gradient(#c9d6db 1px,transparent 1px);background-size:24px 24px}.edge-layer{position:absolute;inset:0;width:2200px;height:1500px;pointer-events:none;overflow:visible}.edge-layer path{fill:none;stroke:#607985;stroke-width:2.2;pointer-events:stroke}.graph-node{position:absolute;width:240px;min-height:104px;background:#fff;border:1px solid #dbe5e7;border-radius:12px;box-shadow:0 8px 22px rgba(46,72,82,.11);cursor:grab;z-index:2}.graph-node.selected{outline:2px solid #1fc875}.graph-node header{display:flex;align-items:center;gap:7px;padding:11px 12px;border-bottom:1px solid #edf2f3}.graph-node header strong{flex:1}.graph-node header button{border:0;background:none}.graph-node p{margin:0;padding:12px;color:#6c7f78;font-size:12px}.input-port,.output-port{position:absolute;width:14px;height:14px;border-radius:50%;border:2px solid #fff;background:#607985;box-shadow:0 0 0 1px #607985}.input-port{left:-8px;top:46px}.output-port{right:-8px;top:46px}.output-port.yes{top:65px}.output-port.no{top:86px}.output-port i{position:absolute;right:17px;top:-4px;font-size:8px;font-style:normal}.connect-hint{position:fixed;bottom:24px;left:50%;background:#173c2e;color:#fff;padding:9px 14px;border-radius:999px}.config-drawer{position:absolute;z-index:20;left:0;top:0;bottom:0;width:540px;background:#fff;box-shadow:12px 0 32px rgba(20,45,35,.16);display:flex;flex-direction:column}.drawer-title{display:flex;gap:14px;align-items:center;padding:25px 34px 18px}.drawer-icon{width:44px;height:44px;border-radius:10px;background:#e8f8ef;display:grid;place-items:center;font-size:20px}.drawer-title h2{margin:0 0 3px;font-size:22px}.drawer-title p{margin:0;color:#7c8b85}.drawer-scroll{padding:0 34px 20px;overflow:auto;flex:1}.config-section{border:1px solid #dce5e1;border-radius:13px;padding:16px;margin-bottom:14px}.config-section header{margin-bottom:14px}.config-section header b,.config-section header small{display:block}.config-section header small{color:#7e8d87;margin-top:3px}.config-section em{font-size:10px;color:#168756;background:#e5f8ee;border-radius:999px;padding:3px 7px;font-style:normal}.config-section label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;margin-bottom:13px}.config-section input,.config-section textarea,.config-section select{border:1px solid #d7e1dd;border-radius:8px;padding:10px;background:#fff;font:inherit}.check{flex-direction:row!important;align-items:center}.match-grid,.two-col,.http-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.match-grid button{padding:12px;text-align:left;border:1px solid #d8e2de;background:#fff;border-radius:9px}.match-grid button.active{border:2px solid #19ad63;background:#f5fcf8}.match-grid b,.match-grid small{display:block}.match-grid small{color:#7e8d87;margin-top:3px}.drawer-footer{padding:15px 16px;border-top:1px solid #e3eae6;display:flex;justify-content:space-between}.drawer-footer button{padding:12px 20px;border-radius:9px;font-weight:800}.drawer-footer .close{background:#fff;border:1px solid #d7e1dd}.drawer-footer .save{background:#16ad63;color:#fff;border:0}.builder-toast{position:fixed;right:22px;bottom:22px;background:#e2f8eb;color:#176a43;padding:10px 15px;border-radius:8px;z-index:50}.builder-toast.error{background:#ffe8e8;color:#a22}@media(max-width:900px){.config-drawer{width:min(540px,100%)}.blocks-panel{display:none}.visual-builder{grid-template-columns:1fr}.flow-picker form{display:none}}
</style>